CREATE TABLE inventory_scopes(plant_id TEXT NOT NULL REFERENCES plants(id),workspace TEXT NOT NULL CHECK(workspace IN('demo','plant')),actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(plant_id,workspace));
CREATE TABLE inventory_parts(plant_id TEXT NOT NULL REFERENCES plants(id),workspace TEXT NOT NULL,part_id TEXT NOT NULL,name TEXT NOT NULL,on_hand INTEGER NOT NULL DEFAULT 0 CHECK(on_hand>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand),version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(plant_id,workspace,part_id),FOREIGN KEY(plant_id,workspace) REFERENCES inventory_scopes(plant_id,workspace));
CREATE TABLE inventory_work_parts(work_order_id TEXT NOT NULL REFERENCES work_orders(id),part_id TEXT NOT NULL,reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0),issued INTEGER NOT NULL DEFAULT 0 CHECK(issued>=0),consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed>=0),returned INTEGER NOT NULL DEFAULT 0 CHECK(returned>=0),PRIMARY KEY(work_order_id,part_id));
CREATE TABLE inventory_movements(id TEXT PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,plant_id TEXT NOT NULL,workspace TEXT NOT NULL,part_id TEXT NOT NULL,work_order_id TEXT REFERENCES work_orders(id),action TEXT NOT NULL,quantity INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,reason TEXT NOT NULL,before_state TEXT NOT NULL,after_state TEXT NOT NULL,FOREIGN KEY(plant_id,workspace,part_id) REFERENCES inventory_parts(plant_id,workspace,part_id));
CREATE INDEX inventory_history ON inventory_movements(plant_id,workspace,part_id,created_at);
CREATE INDEX inventory_work_history ON inventory_movements(work_order_id,created_at);
CREATE TABLE inventory_commands(actor_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,payload TEXT NOT NULL,movement_id TEXT NOT NULL REFERENCES inventory_movements(id),PRIMARY KEY(actor_id,request_key));
